// Stock Average Cost Calculator — DOM wiring.
// Safe DOM only: textContent / value. User input is never used as markup,
// style, selector, href, src, or a file name. No fetch, storage, analytics,
// or remote assets. The calculation runs in a module Worker built from the
// fixed embedded core bytes (js/worker-source.mjs, generated by the preview
// build); a Worker failure keeps the draft for retry.

import { createController } from './controller.mjs';
import { msg } from './i18n.mjs';

const lang = document.documentElement.lang === 'en' ? 'en' : 'zh-Hant';
const MAX_ROWS = 20;

// The SPEC-pinned example: fixtures.json case fifo-sell-two-lots.
const EXAMPLE = {
  feeRateBps: '0',
  trades: [
    { side: 'buy', shares: '100', price: '10' },
    { side: 'buy', shares: '100', price: '20' },
    { side: 'sell', shares: '150', price: '25' },
  ],
};

function $(id) {
  return document.getElementById(id);
}

const feeInput = $('fee-input');
const tradesBody = $('trades-body');
const addRowButton = $('add-row-button');
const rowLimitNote = $('row-limit-note');
const runButton = $('run-button');
const exampleButton = $('example-button');
const resetButton = $('reset-button');
const cancelButton = $('cancel-button');
const downloadButton = $('download-button');
const statusRegion = $('status');
const statusText = $('status-text');
const errorBox = $('error-box');
const errorText = $('error-text');
const exampleNote = $('example-note');
const resultSection = $('result-section');
const resultSummary = $('result-summary');
const averageNote = $('average-note');
const sellsBody = $('sells-table-body');
const sellsEmpty = $('sells-empty');
const lotsBody = $('lots-table-body');
const lotsEmpty = $('lots-empty');

let exampleJustLoaded = false;
let previousStatus = 'empty';
let downloadUrl = null;
let downloadTimer = null;

function revokeDownload() {
  if (downloadUrl !== null) {
    URL.revokeObjectURL(downloadUrl);
    downloadUrl = null;
  }
  if (downloadTimer !== null) {
    clearTimeout(downloadTimer);
    downloadTimer = null;
  }
}

// Real worker factory: the Worker source is the fixed core bytes plus the
// fixed message handler, embedded at build time. User content never takes
// part in the program.
async function createRealWorker(callbacks) {
  const { WORKER_SOURCE } = await import('./worker-source.mjs');
  const url = URL.createObjectURL(
    new Blob([WORKER_SOURCE], { type: 'text/javascript' }),
  );
  const worker = new Worker(url, { type: 'module' });
  worker.onmessage = (event) => callbacks.onMessage(event.data);
  worker.onerror = () => callbacks.onError();
  return {
    postMessage(message) {
      worker.postMessage(message);
    },
    terminate() {
      worker.terminate();
      URL.revokeObjectURL(url);
    },
  };
}

// ---- Trade-row editor -------------------------------------------------

function rowControls(rowEl) {
  return {
    side: rowEl.querySelector('.side-select'),
    shares: rowEl.querySelector('.shares-input'),
    price: rowEl.querySelector('.price-input'),
    up: rowEl.querySelector('.move-up'),
    down: rowEl.querySelector('.move-down'),
    del: rowEl.querySelector('.delete-row'),
  };
}

function makeRow(trade, index, total) {
  const tr = document.createElement('tr');

  const sideCell = document.createElement('td');
  const select = document.createElement('select');
  select.className = 'side-select';
  const buyOption = document.createElement('option');
  buyOption.value = 'buy';
  buyOption.textContent = msg(lang, 'buyOption');
  const sellOption = document.createElement('option');
  sellOption.value = 'sell';
  sellOption.textContent = msg(lang, 'sellOption');
  select.appendChild(buyOption);
  select.appendChild(sellOption);
  select.value = trade.side === 'sell' ? 'sell' : 'buy';
  select.setAttribute('aria-label', msg(lang, 'sideLabel', { row: index + 1 }));
  sideCell.appendChild(select);
  tr.appendChild(sideCell);

  const sharesCell = document.createElement('td');
  const shares = document.createElement('input');
  shares.className = 'shares-input';
  shares.type = 'text';
  shares.inputMode = 'numeric';
  shares.autocomplete = 'off';
  shares.value = trade.shares;
  shares.setAttribute('aria-label', msg(lang, 'sharesLabel', { row: index + 1 }));
  sharesCell.appendChild(shares);
  tr.appendChild(sharesCell);

  const priceCell = document.createElement('td');
  const price = document.createElement('input');
  price.className = 'price-input';
  price.type = 'text';
  price.inputMode = 'decimal';
  price.autocomplete = 'off';
  price.value = trade.price;
  price.setAttribute('aria-label', msg(lang, 'priceLabel', { row: index + 1 }));
  priceCell.appendChild(price);
  tr.appendChild(priceCell);

  const actionCell = document.createElement('td');
  actionCell.className = 'row-actions';
  const up = document.createElement('button');
  up.type = 'button';
  up.className = 'move-up small';
  up.textContent = '↑';
  up.setAttribute('aria-label', msg(lang, 'moveUpLabel', { row: index + 1 }));
  up.disabled = index === 0;
  const down = document.createElement('button');
  down.type = 'button';
  down.className = 'move-down small';
  down.textContent = '↓';
  down.setAttribute('aria-label', msg(lang, 'moveDownLabel', { row: index + 1 }));
  down.disabled = index === total - 1;
  const del = document.createElement('button');
  del.type = 'button';
  del.className = 'delete-row small';
  del.textContent = '×';
  del.setAttribute('aria-label', msg(lang, 'deleteRowLabel', { row: index + 1 }));
  del.disabled = total <= 1;
  actionCell.appendChild(up);
  actionCell.appendChild(down);
  actionCell.appendChild(del);
  tr.appendChild(actionCell);

  return tr;
}

// Rebuild every row from a draft (used on load, example, and reset — never
// on keystrokes, so focus and caret stay put while typing).
function buildRows(draft) {
  while (tradesBody.firstChild !== null) tradesBody.removeChild(tradesBody.firstChild);
  draft.trades.forEach((trade, index) => {
    tradesBody.appendChild(makeRow(trade, index, draft.trades.length));
  });
}

// Refresh per-row labels and button availability after rows move or change
// count, without touching input values.
function refreshRowAffordances() {
  const rows = [...tradesBody.querySelectorAll('tr')];
  rows.forEach((rowEl, index) => {
    const controls = rowControls(rowEl);
    controls.side.setAttribute('aria-label', msg(lang, 'sideLabel', { row: index + 1 }));
    controls.shares.setAttribute('aria-label', msg(lang, 'sharesLabel', { row: index + 1 }));
    controls.price.setAttribute('aria-label', msg(lang, 'priceLabel', { row: index + 1 }));
    controls.up.setAttribute('aria-label', msg(lang, 'moveUpLabel', { row: index + 1 }));
    controls.down.setAttribute('aria-label', msg(lang, 'moveDownLabel', { row: index + 1 }));
    controls.del.setAttribute('aria-label', msg(lang, 'deleteRowLabel', { row: index + 1 }));
    controls.up.disabled = index === 0;
    controls.down.disabled = index === rows.length - 1;
    controls.del.disabled = rows.length <= 1;
  });
}

function readDraft() {
  const trades = [...tradesBody.querySelectorAll('tr')].map((rowEl) => {
    const controls = rowControls(rowEl);
    return {
      side: controls.side.value,
      shares: controls.shares.value,
      price: controls.price.value,
    };
  });
  return { feeRateBps: feeInput.value, trades };
}

// ---- Result rendering ---------------------------------------------------

function cell(text, mono = false) {
  const td = document.createElement('td');
  td.textContent = text;
  if (mono) td.className = 'mono';
  return td;
}

function pnlText(value) {
  if (value.startsWith('-')) return `${value} (${msg(lang, 'pnlLoss')})`;
  if (value !== '0.0000') return `${value} (${msg(lang, 'pnlProfit')})`;
  return value;
}

function summaryRow(term, value) {
  const dt = document.createElement('dt');
  dt.textContent = term;
  const dd = document.createElement('dd');
  dd.textContent = value;
  dd.className = 'mono';
  return [dt, dd];
}

function renderResult(result) {
  while (resultSummary.firstChild !== null) resultSummary.removeChild(resultSummary.firstChild);
  const rows = [
    summaryRow(msg(lang, 'summaryShares'), String(result.totalSharesHeld)),
    summaryRow(msg(lang, 'summaryCost'), result.totalCostBasis),
    summaryRow(
      msg(lang, 'summaryAverage'),
      result.averageCostPerShare === null ? '—' : result.averageCostPerShare,
    ),
    summaryRow(msg(lang, 'summaryPnl'), pnlText(result.totalRealizedPnl)),
    summaryRow(msg(lang, 'summaryFees'), result.totalFees),
  ];
  for (const [dt, dd] of rows) {
    resultSummary.appendChild(dt);
    resultSummary.appendChild(dd);
  }
  averageNote.hidden = result.averageCostPerShare !== null;

  while (sellsBody.firstChild !== null) sellsBody.removeChild(sellsBody.firstChild);
  sellsEmpty.hidden = result.sells.length !== 0;
  for (const sell of result.sells) {
    const tr = document.createElement('tr');
    tr.appendChild(cell(String(sell.row)));
    tr.appendChild(cell(String(sell.shares)));
    tr.appendChild(cell(sell.proceeds, true));
    tr.appendChild(cell(sell.costRelieved, true));
    tr.appendChild(cell(pnlText(sell.realizedPnl), true));
    sellsBody.appendChild(tr);
  }

  while (lotsBody.firstChild !== null) lotsBody.removeChild(lotsBody.firstChild);
  lotsEmpty.hidden = result.remainingLots.length !== 0;
  result.remainingLots.forEach((lot, index) => {
    const tr = document.createElement('tr');
    tr.appendChild(cell(msg(lang, 'colLotIndex', { index: index + 1 })));
    tr.appendChild(cell(String(lot.shares)));
    tr.appendChild(cell(lot.costBasis, true));
    lotsBody.appendChild(tr);
  });
}

// ---- Error focus / marking ----------------------------------------------

function errorTarget(error) {
  if (error === null) return null;
  if (error.field === 'feeRateBps') return feeInput;
  if (error.row !== null && error.row >= 1) {
    const rowEl = tradesBody.querySelectorAll('tr')[error.row - 1];
    if (rowEl !== undefined) {
      const controls = rowControls(rowEl);
      if (error.field === 'side') return controls.side;
      if (error.field === 'price') return controls.price;
      return controls.shares; // shares errors and OVERSOLD focus shares.
    }
    if (error.code === 'ROW_LIMIT') return addRowButton;
  }
  return null;
}

function clearErrorMarks() {
  for (const el of [feeInput, ...tradesBody.querySelectorAll('input, select')]) {
    el.removeAttribute('aria-invalid');
    el.removeAttribute('aria-errormessage');
  }
}

function describeError(error) {
  if (error === null) return '';
  const field = error.field === null
    ? ''
    : msg(lang, `field${error.field[0].toUpperCase()}${error.field.slice(1)}`);
  return msg(lang, `error${error.code}`, { row: error.row ?? '', field });
}

// ---- Main render ----------------------------------------------------------

function render(state) {
  const wasBusy = previousStatus === 'busy';
  previousStatus = state.status;

  statusRegion.setAttribute('aria-busy', state.status === 'busy' ? 'true' : 'false');
  if (state.status === 'success') statusRegion.dataset.tone = 'success';
  else if (state.status === 'error') statusRegion.dataset.tone = 'error';
  else if (state.status === 'dirty' || state.status === 'cancelled') statusRegion.dataset.tone = 'warning';
  else delete statusRegion.dataset.tone;

  runButton.disabled = state.status === 'busy';
  cancelButton.hidden = state.status !== 'busy';
  downloadButton.hidden = state.status !== 'success';
  exampleNote.hidden = !exampleJustLoaded;
  addRowButton.disabled = state.draft.trades.length >= MAX_ROWS;
  rowLimitNote.hidden = state.draft.trades.length < MAX_ROWS;

  if (state.status === 'success' && state.result !== null) {
    resultSection.hidden = false;
    renderResult(state.result);
  } else {
    resultSection.hidden = true;
  }

  clearErrorMarks();
  if (state.status === 'error' && state.error !== null) {
    errorBox.hidden = false;
    errorText.textContent = describeError(state.error);
    const target = errorTarget(state.error);
    if (target !== null && target !== addRowButton) {
      target.setAttribute('aria-invalid', 'true');
      target.setAttribute('aria-errormessage', 'error-box');
    }
    // Only a submission failure moves focus to the first error field.
    if (wasBusy && target !== null) target.focus();
  } else {
    errorBox.hidden = true;
    errorText.textContent = '';
  }

  if (state.status !== 'success') revokeDownload();

  if (state.status === 'empty') {
    statusText.textContent = msg(lang, 'statusEmpty');
  } else if (state.status === 'dirty') {
    statusText.textContent = exampleJustLoaded
      ? `${msg(lang, 'exampleLoaded')} ${msg(lang, 'statusDirty')}`
      : msg(lang, 'statusDirty');
  } else if (state.status === 'busy') {
    statusText.textContent = msg(lang, 'statusBusy');
  } else if (state.status === 'success') {
    statusText.textContent = `${msg(lang, 'statusSuccess')} ${msg(lang, 'reportReady')}`;
  } else if (state.status === 'error') {
    statusText.textContent = msg(lang, 'statusError');
  } else if (state.status === 'cancelled') {
    statusText.textContent = msg(lang, 'statusCancelled');
  }
}

const controller = createController({
  createWorker: createRealWorker,
  onChange: render,
});

function syncDraft() {
  render(controller.setDraft(readDraft()));
}

feeInput.addEventListener('input', () => {
  exampleJustLoaded = false;
  syncDraft();
});

tradesBody.addEventListener('input', () => {
  exampleJustLoaded = false;
  syncDraft();
});

tradesBody.addEventListener('change', () => {
  exampleJustLoaded = false;
  syncDraft();
});

tradesBody.addEventListener('click', (event) => {
  const button = event.target.closest('button');
  if (button === null) return;
  const rowEl = button.closest('tr');
  if (rowEl === null) return;
  const rows = [...tradesBody.querySelectorAll('tr')];
  const index = rows.indexOf(rowEl);
  exampleJustLoaded = false;
  if (button.classList.contains('move-up') && index > 0) {
    tradesBody.insertBefore(rowEl, rows[index - 1]);
  } else if (button.classList.contains('move-down') && index < rows.length - 1) {
    tradesBody.insertBefore(rows[index + 1], rowEl);
  } else if (button.classList.contains('delete-row') && rows.length > 1) {
    tradesBody.removeChild(rowEl);
  } else {
    return;
  }
  refreshRowAffordances();
  syncDraft();
});

addRowButton.addEventListener('click', () => {
  const draft = readDraft();
  if (draft.trades.length >= MAX_ROWS) return;
  draft.trades.push({ side: 'buy', shares: '', price: '' });
  exampleJustLoaded = false;
  buildRows(draft);
  render(controller.setDraft(draft));
  const rows = tradesBody.querySelectorAll('tr');
  const controls = rowControls(rows[rows.length - 1]);
  controls.shares.focus();
});

runButton.addEventListener('click', () => {
  exampleJustLoaded = false;
  render(controller.run());
});

exampleButton.addEventListener('click', () => {
  exampleJustLoaded = true;
  feeInput.value = EXAMPLE.feeRateBps;
  buildRows(EXAMPLE);
  render(controller.loadExample(EXAMPLE));
  feeInput.focus();
});

resetButton.addEventListener('click', () => {
  exampleJustLoaded = false;
  const state = controller.reset();
  feeInput.value = state.draft.feeRateBps;
  buildRows(state.draft);
  render(state);
  feeInput.focus();
});

cancelButton.addEventListener('click', () => {
  render(controller.cancel());
});

downloadButton.addEventListener('click', () => {
  const payload = controller.download();
  if (payload === null) return;
  revokeDownload();
  const blob = new Blob([payload.text], { type: 'application/json' });
  downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = downloadUrl;
  anchor.download = payload.filename;
  anchor.click();
  downloadTimer = setTimeout(revokeDownload, 30000);
});

window.addEventListener('pagehide', () => {
  controller.dispose();
  revokeDownload();
});

window.addEventListener('pageshow', (event) => {
  if (event.persisted) {
    exampleJustLoaded = false;
    const state = controller.reset();
    feeInput.value = state.draft.feeRateBps;
    buildRows(state.draft);
    render(state);
  }
});

buildRows(controller.getState().draft);
render(controller.getState());
